import{_ as a,o as i,c as o,a2 as r}from"./chunks/framework.DCVnL8g5.js";const h=JSON.parse('{"title":"Buenas practicas de CI/CD","description":"","frontmatter":{},"headers":[],"relativePath":"devops/cicd/07-buenas-practicas.md","filePath":"devops/cicd/07-buenas-practicas.md","lastUpdated":1789040978000,"isDraft":false}'),t={name:"devops/cicd/07-buenas-practicas.md"};function n(l,e,s,d,c,u){return i(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="buenas-practicas-de-ci-cd" tabindex="-1">Buenas practicas de CI/CD <a class="header-anchor" href="#buenas-practicas-de-ci-cd" aria-label="Permalink to &quot;Buenas practicas de CI/CD&quot;">​</a></h1><p>Este capitulo cierra el manual con recomendaciones transversales para equipos que ya tienen pipelines basicos y quieren madurar hacia entrega continua fiable.</p><h2 id="cultura-y-flujo-de-trabajo" tabindex="-1">Cultura y flujo de trabajo <a class="header-anchor" href="#cultura-y-flujo-de-trabajo" aria-label="Permalink to &quot;Cultura y flujo de trabajo&quot;">​</a></h2><ul><li><strong>Main siempre verde:</strong> un pipeline roto en <code>main</code> es prioridad P1.</li><li><strong>PRs pequenos:</strong> menos riesgo, revision mas facil, rollback mas simple.</li><li><strong>Trunk-based development:</strong> ramas cortas; feature flags para trabajo largo.</li><li><strong>Revision de codigo obligatoria:</strong> el CI no sustituye ojos humanos en diseno y seguridad.</li></ul><h2 id="diseno-de-pipelines" tabindex="-1">Diseno de pipelines <a class="header-anchor" href="#diseno-de-pipelines" aria-label="Permalink to &quot;Diseno de pipelines&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Rapido y frecuente en PR  |  Completo en main / nightly</span></span>
<span class="line"><span>-------------------------|---------------------------</span></span>
<span class="line"><span>lint, unit test          |  integration, e2e, security scan</span></span>
<span class="line"><span>&lt; 10 min objetivo        |  &lt; 45 min aceptable</span></span></code></pre></div><ul><li>Falla rapido: lint antes que e2e.</li><li>Paraleliza jobs independientes.</li><li>Usa <code>paths</code> / <code>paths-ignore</code> en monorepos.</li><li>Reutiliza workflows (<code>workflow_call</code>) y composite actions.</li></ul><h2 id="reproducibilidad" tabindex="-1">Reproducibilidad <a class="header-anchor" href="#reproducibilidad" aria-label="Permalink to &quot;Reproducibilidad&quot;">​</a></h2><ul><li>Lockfiles commiteados.</li><li>Imagenes base con version o digest fijo.</li><li>Mismo Dockerfile en dev y CI.</li><li>Variables de entorno documentadas en <code>.env.example</code>.</li></ul><h2 id="seguridad-integrada-devsecops" tabindex="-1">Seguridad integrada (DevSecOps) <a class="header-anchor" href="#seguridad-integrada-devsecops" aria-label="Permalink to &quot;Seguridad integrada (DevSecOps)&quot;">​</a></h2><ul><li>Secretos en vault / GitHub Secrets, nunca en repo.</li><li>Principio de minimo privilegio en tokens de CI.</li><li>Rotacion periodica de credenciales de deploy.</li><li>Firmar artefactos y verificar en deploy.</li><li>Auditar quien puede lanzar produccion.</li></ul><h2 id="entornos" tabindex="-1">Entornos <a class="header-anchor" href="#entornos" aria-label="Permalink to &quot;Entornos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entorno</th><th>Proposito</th></tr></thead><tbody><tr><td>Local</td><td>Desarrollo rapido</td></tr><tr><td>CI</td><td>Validacion automatica</td></tr><tr><td>Staging</td><td>Replica de prod, QA, demos</td></tr><tr><td>Production</td><td>Usuarios finales</td></tr></tbody></table><p>Staging debe parecerse a prod en:</p><ul><li>Version de runtime y dependencias.</li><li>Configuracion (con secretos distintos).</li><li>Topologia (Kubernetes, no solo docker-compose si prod es k8s).</li></ul><h2 id="metricas-dora-referencia" tabindex="-1">Metricas DORA (referencia) <a class="header-anchor" href="#metricas-dora-referencia" aria-label="Permalink to &quot;Metricas DORA (referencia)&quot;">​</a></h2><ol><li><strong>Deployment frequency</strong> — con que frecuencia desplegais.</li><li><strong>Lead time for changes</strong> — commit a produccion.</li><li><strong>Change failure rate</strong> — % cambios que degradan servicio.</li><li><strong>Time to restore</strong> — tiempo en recuperar tras fallo.</li></ol><p>Mejorar CI/CD impacta directamente en estas cuatro metricas.</p><h2 id="documentacion-viva" tabindex="-1">Documentacion viva <a class="header-anchor" href="#documentacion-viva" aria-label="Permalink to &quot;Documentacion viva&quot;">​</a></h2><p>Mantener en el repo:</p><ul><li><code>CONTRIBUTING.md</code> — como correr tests y abrir PR.</li><li>Runbooks de deploy y rollback.</li><li>Diagrama de pipeline (aunque sea ASCII en markdown).</li><li>Owners por servicio (<code>CODEOWNERS</code>).</li></ul><h2 id="relacion-con-otros-manuales" tabindex="-1">Relacion con otros manuales <a class="header-anchor" href="#relacion-con-otros-manuales" aria-label="Permalink to &quot;Relacion con otros manuales&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Necesidad</th><th>Manual</th></tr></thead><tbody><tr><td>Workflows concretos en GitHub</td><td><a href="./../../cloud/github-actions/01-introduccion-a-workflows">GitHub Actions</a></td></tr><tr><td>Contenedores</td><td><a href="./../../herramientas/docker/01-introduccion">Docker</a></td></tr><tr><td>Orquestacion</td><td><a href="./../../cloud/kubernetes/01-introduccion-y-arquitectura">Kubernetes</a></td></tr><tr><td>Infra como codigo</td><td><a href="./../terraform/01-introduccion-e-instalacion">Terraform</a></td></tr><tr><td>Automatizacion shell</td><td><a href="./../bash/01-introduccion-y-terminal">Bash</a></td></tr></tbody></table><h2 id="checklist-de-madurez" tabindex="-1">Checklist de madurez <a class="header-anchor" href="#checklist-de-madurez" aria-label="Permalink to &quot;Checklist de madurez&quot;">​</a></h2><h3 id="nivel-inicial" tabindex="-1">Nivel inicial <a class="header-anchor" href="#nivel-inicial" aria-label="Permalink to &quot;Nivel inicial&quot;">​</a></h3><ul><li>[ ] CI en cada PR (lint + test)</li><li>[ ] Build automatico en main</li><li>[ ] Secretos fuera del repo</li></ul><h3 id="nivel-intermedio" tabindex="-1">Nivel intermedio <a class="header-anchor" href="#nivel-intermedio" aria-label="Permalink to &quot;Nivel intermedio&quot;">​</a></h3><ul><li>[ ] Deploy automatico a staging</li><li>[ ] Artefactos versionados por SHA</li><li>[ ] Smoke test post-deploy</li><li>[ ] Escaneo de dependencias</li></ul><h3 id="nivel-avanzado" tabindex="-1">Nivel avanzado <a class="header-anchor" href="#nivel-avanzado" aria-label="Permalink to &quot;Nivel avanzado&quot;">​</a></h3><ul><li>[ ] Canary o blue-green</li><li>[ ] Feature flags</li><li>[ ] Metricas DORA visibles</li><li>[ ] Rollback probado y documentado</li><li>[ ] SBOM y firma de imagenes</li></ul><h2 id="errores-que-frenan-equipos" tabindex="-1">Errores que frenan equipos <a class="header-anchor" href="#errores-que-frenan-equipos" aria-label="Permalink to &quot;Errores que frenan equipos&quot;">​</a></h2><ul><li>Pipeline de 60 min que nadie respeta.</li><li>&quot;Funciona en mi maquina&quot; sin paridad con CI.</li><li>Desplegar viernes tarde sin observabilidad.</li><li>15 pipelines copy-paste desincronizados.</li><li>Confundir &quot;tenemos Jenkins&quot; con &quot;hacemos CI/CD bien&quot;.</li></ul><h2 id="cierre" tabindex="-1">Cierre <a class="header-anchor" href="#cierre" aria-label="Permalink to &quot;Cierre&quot;">​</a></h2><p>CI/CD no es una herramienta: es el camino desde un commit hasta valor en produccion con feedback rapido. Itera el pipeline como iteras el producto: mide, simplifica, automatiza y reduce riesgo en cada ciclo.</p><p>Este repositorio aplica parte de estas practicas: el workflow <a href="../../../.github/workflows/validate.yml">Validate documentation</a> valida build y enlaces; <a href="../../../.github/workflows/deploy.yml">Deploy documentation</a> publica la web en cada push a <code>main</code>.</p>`,35)])])}const m=a(t,[["render",n]]);export{h as __pageData,m as default};
